    n = int(n)
    if n == 0: return 'sıfır'
    out = []
    for val, name in ((10**9, 'milyar'), (10**6, 'milyon'), (1000, 'bin')):
        g = n // val
        n = n % val
        if g:
            if val == 1000 and g == 1: out.append('bin')
            else: out.append(w3(g) + ' ' + name)
    if n: out.append(w3(n))
    return ' '.join(out)
