                    else:
                        s = CUR[c][0] + ' borcunuz ' + money(sd, c) + ', kalan toplam borcunuz ' + money(rd, c) + ', ödenmesi gereken minimum tutar ' + money(mp, c) + '.'
                    parts.append(pre + s if pre else s)
